    // ------------------------------------------------------------
    // Habillage visuel des proxys (icône + couleur) dans le menu
    // ------------------------------------------------------------

    // ------------------------------------------------------------
    // LANGUE : FRANÇAIS / ANGLAIS
    // ------------------------------------------------------------
    //
    // Français si Twitch (ou à défaut le navigateur) est en français,
    // anglais sinon. Un clic sur un drapeau du menu fige le choix
    // (pageConfig.lang = 'fr' | 'en' ; 'auto' = détection).
    //
    // Deux outils :
    // - tt('texte fr', 'text en') pour les textes écrits par le code ;
    // - UI_EN (français -> anglais) pour les textes FIXES des gabarits
    //   HTML, appliqué par translateStatic() après chaque rendu. Le
    //   texte d'origine est gardé sur le nœud : on repasse en
    //   français sans rien reconstruire.
    function detectLang() {
        var lang = '';
        try {
            lang = document.documentElement.getAttribute('lang') || '';
        } catch (e) {}
        if (!lang) {
            try {
                lang = navigator.language || '';
            } catch (e) {}
        }
        return /^fr/i.test(lang) ? 'fr' : 'en';
    }

    function uiLang() {
        var chosen = typeof pageConfig !== 'undefined' && pageConfig && pageConfig.lang;
        return chosen === 'fr' || chosen === 'en' ? chosen : detectLang();
    }

    function tt(fr, en) {
        return uiLang() === 'en' ? en : fr;
    }

    function uiLocale() {
        return uiLang() === 'en' ? 'en-GB' : 'fr-FR';
    }

