    var UI_FR = {};
    Object.keys(UI_EN).forEach(function (fr) {
        if (UI_EN[fr] !== fr) {
            UI_FR[UI_EN[fr]] = fr;
        }
    });

    var I18N_ATTRS = ['data-tp9-tip', 'data-tp9-tip-sub', 'placeholder', 'aria-label'];

    // Une valeur (texte ou attribut) dans la langue voulue. « state »
    // retient les deux versions ; il est oublié si le code a réécrit
    // la valeur entre-temps.
    function i18nValue(value, state, en) {
        if (state && value !== state.fr && value !== state.en) {
            state = null;
        }
        if (!state) {
            var key = value.replace(/\s+/g, ' ').trim();
            var other = en ? UI_EN[key] : UI_FR[key];
            if (!other) {
                return null;
            }
            var swapped = value.match(/^\s*/)[0] + other + value.match(/\s*$/)[0];
            state = en ? { fr: value, en: swapped } : { fr: swapped, en: value };
        }
        return state;
    }

    function translateStatic(root) {
        if (!root) {
            return;
        }
        var en = uiLang() === 'en';
        // data-tp9-raw : noms de chaînes, messages de logs… jamais
        // traduits, même s'ils tombent sur un mot du dictionnaire.
        var walker = document.createTreeWalker(root, 5, {
            acceptNode: function (n) {
                return n.nodeType === 1
                    ? (n.hasAttribute('data-tp9-raw') ? 2 : 3)
                    : 1;
            }
        });
        var node;
        while ((node = walker.nextNode())) {
            var state = i18nValue(node.nodeValue, node.__tp9i18n, en);
            if (!state) {
                continue;
            }
            node.__tp9i18n = state;
            var want = en ? state.en : state.fr;
            if (node.nodeValue !== want) {
                node.nodeValue = want;
            }
        }
        root.querySelectorAll('[data-tp9-tip],[data-tp9-tip-sub],[placeholder],[aria-label]').forEach(function (el) {
            if (el.closest('[data-tp9-raw]')) {
                return;
            }
            I18N_ATTRS.forEach(function (name) {
                var value = el.getAttribute(name);
                if (!value) {
                    return;
                }
                el.__tp9i18nAttr = el.__tp9i18nAttr || {};
                var state = i18nValue(value, el.__tp9i18nAttr[name], en);
                if (!state) {
                    return;
                }
                el.__tp9i18nAttr[name] = state;
                var want = en ? state.en : state.fr;
                if (value !== want) {
                    el.setAttribute(name, want);
                }
            });
        });
    }

    // Icônes du menu : dessinées, pour rendre pareil partout (un emoji
    // change d'aspect selon le système).
    function tp9Icon(size, paths) {
        return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 24 24" fill="none"' +
            ' stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"' +
            ' aria-hidden="true">' + paths + '</svg>';
    }

    function tp9OptIcon(paths) {
        return '<span class="tp9-opt-ico" aria-hidden="true">' + tp9Icon(14, paths) + '</span>';
    }

