        var dayKey = dateKeyFor(now2);

        pageStats.dailyWatchTime[dayKey] = (pageStats.dailyWatchTime[dayKey] || 0) + watchedMs;

        pruneDailyMap(pageStats.dailyWatchTime);

        var hourKey = hourKeyFor(now2);

        pageStats.hourlyWatchTime[hourKey] = (pageStats.hourlyWatchTime[hourKey] || 0) + watchedMs;

        pruneHourlyMap(pageStats.hourlyWatchTime);

