    function formatBytes(bytes) {
        if (!bytes) {
            return tt('0 Mo', '0 MB');
        }

        var mb = bytes / (1024 * 1024);

        // Passe en Go dès 1000 Mo plutôt qu'à 1024, pour éviter
        // d'afficher des valeurs à 3-4 chiffres pleines de zéros.
        if (mb >= 1000) {
            return (mb / 1000).toFixed(2) + tt(' Go', ' GB');
        }

        return mb.toFixed(1) + tt(' Mo', ' MB');
    }

    function formatNumber(n) {
        var num = Number(n) || 0;
        return num.toLocaleString(typeof uiLocale === 'function' ? uiLocale() : 'fr-FR');
    }

    function formatDuration(ms) {
        if (!ms) {
            return '0 min';
        }

        var totalMinutes = Math.round(ms / 60000);

        var hours = Math.floor(totalMinutes / 60);
        var minutes = totalMinutes % 60;

        if (hours > 0) {
            return hours + 'h' + (minutes < 10 ? '0' : '') + minutes;
        }

        return minutes + ' min';
    }

